import itertools
import numpy as np

def check_triple(a, b, c):
    diff = [b-a, c-b]
    if sorted(diff) in [[n-1, n], [n, n+1], [n-1, n+1]]:
        return True
    return False

def find_division(n):
    numbers = list(range(1, 3*n+1))
    division = []
    for t in itertools.combinations(numbers, 3):
        if check_triple(*t):
            division.append(t)
            numbers = [x for x in numbers if x not in t]
            if len(numbers) == 0:
                break
    if len(division) == n:
        return division
    else:
        return None

n = 16
result = find_division(n)
if result is not None:
    print(result)
else:
    print("No valid division found")
